// Noctalia colors for Spicetify.
//
// Generated by Noctalia from a template: do not edit, your changes are
// overwritten on the next theme change.
//
// Every Spicetify theme takes its colors from --spice-<key> CSS variables.
// This extension sets them to Noctalia's colors on top of whatever theme is
// active (Marketplace or local), so the theme keeps its layout and styling
// and only the colors follow Noctalia. Toggle it from the profile menu:
// "Noctalia colors". Off = the theme's own color scheme.
//
// When Noctalia's colors change, the template hook runs `spicetify refresh -e`;
// this extension re-reads its own file every few seconds and picks the new
// colors up without restarting Spotify (if that ever fails, they apply on
// the next start).

(function noctaliaColors(attempt) {
  attempt = attempt || 0;
  if (!(window.Spicetify && Spicetify.Menu && Spicetify.LocalStorage)) {
    // Spicetify's API loads after extensions start; give up after ~30 s
    // (a Spicetify too old to have the menu API).
    if (attempt < 100) setTimeout(() => noctaliaColors(attempt + 1), 300);
    return;
  }
  // Loaded twice (e.g. after `spicetify refresh -e`)? Keep one menu item and
  // one poll loop.
  if (window.__noctaliaColorsLoaded) return;
  window.__noctaliaColorsLoaded = true;

  // Standard Spicetify keys first, then extra keys used by popular themes
  // (Text, Comfy, Colorful). Themes ignore keys they do not use.
  let colors = /* NOCTALIA-COLORS-BEGIN */ {
    "text": "e5e3d7",
    "subtext": "c8c8b4",
    "main": "13140d",
    "main-elevated": "202019",
    "highlight": "2a2a23",
    "highlight-elevated": "35352e",
    "sidebar": "1b1c15",
    "player": "1b1c15",
    "card": "202019",
    "shadow": "000000",
    "selected-row": "e5e3d7",
    "button": "ccd975",
    "button-active": "d8e295",
    "button-disabled": "919280",
    "tab-active": "2a2a23",
    "notification": "97e2a5",
    "notification-error": "ffb4ab",
    "misc": "474839",
    "accent": "ccd975",
    "accent-active": "d8e295",
    "accent-inactive": "13140d",
    "banner": "ccd975",
    "border-active": "ccd975",
    "border-inactive": "474839",
    "header": "919280",
    "main-transition": "0e0f08",
    "play-button": "ccd975",
    "play-button-active": "d8e295",
    "progress-fg": "ccd975",
    "progress-bg": "35352e",
    "heart": "ffb4ab",
    "pagelink-active": "ccd975",
    "radio-btn-active": "ccd975"
  } /* NOCTALIA-COLORS-END */;

  const STORAGE_KEY = "noctalia:enabled";
  const STYLE_ID = "noctalia-colors";
  const POLL_MS = 5000;

  let enabled = Spicetify.LocalStorage.get(STORAGE_KEY) !== "0"; // on by default

  function rgb(hex) {
    const n = parseInt(hex, 16);
    return ((n >> 16) & 255) + "," + ((n >> 8) & 255) + "," + (n & 255);
  }

  // A <style> at the end of <head> with !important wins over the theme's
  // and Marketplace's own :root color variables.
  function render() {
    let style = document.getElementById(STYLE_ID);
    if (!enabled) {
      if (style) style.remove();
      return;
    }
    if (!style) {
      style = document.createElement("style");
      style.id = STYLE_ID;
    }
    const lines = [];
    for (const key of Object.keys(colors)) {
      const hex = colors[key];
      if (!/^[0-9a-fA-F]{6}$/.test(hex)) continue;
      lines.push("--spice-" + key + ": #" + hex + " !important;");
      lines.push("--spice-rgb-" + key + ": " + rgb(hex) + " !important;");
    }
    style.textContent = ":root {\n  " + lines.join("\n  ") + "\n}";
    document.head.appendChild(style); // (re)append so it stays last
  }

  new Spicetify.Menu.Item("Noctalia colors", enabled, (item) => {
    enabled = !enabled;
    item.setState(enabled);
    Spicetify.LocalStorage.set(STORAGE_KEY, enabled ? "1" : "0");
    render();
  }).register();

  render();

  // Live update: re-read this extension's own file, exactly as Spicetify
  // injected it (<script src="extensions/noctalia.js">, same origin as
  // Spotify's UI). Nothing else is ever fetched.
  const script = document.querySelector('script[src="extensions/noctalia.js"]');
  if (!script) return;
  let own;
  try {
    own = new URL(script.src, location.href);
  } catch (_e) {
    return;
  }
  if (own.origin !== location.origin || !own.pathname.endsWith("/extensions/noctalia.js")) return;
  own.search = "";
  own.hash = "";
  const url = own.href;
  let last = JSON.stringify(colors);
  setInterval(async () => {
    try {
      const res = await fetch(url + "?t=" + Date.now(), { cache: "no-store" });
      const text = await res.text();
      const m = text.match(/NOCTALIA-COLORS-BEGIN \*\/([\s\S]*?)\/\* NOCTALIA-COLORS-END/);
      if (!m) return;
      const next = JSON.parse(m[1]);
      const nextText = JSON.stringify(next);
      if (nextText !== last) {
        last = nextText;
        colors = next;
        render();
      }
    } catch (_e) {
      // Not available in this Spotify build; colors apply on the next start.
    }
  }, POLL_MS);
})();
